import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes1')
from h import *
X=[]
X.append(r(9277390,"Hongos portobello veganos rellenos estilo lasaña","Estos hongos portobello veganos rellenos están generosamente llenos de un relleno de ricota «quesosa» de espinacas y cubiertos con una rica salsa boloñesa, para satisfacer su antojo de lasaña.","6 porciones","1 porción",
[ "6 hongos portobello limpios con un cepillo",
("Para la ricota","1.5 tazas de anacardos (nueces de la India) crudos"),("Para la ricota","1 cucharada de vinagre de sidra de manzana"),("Para la ricota","¼ taza de levadura nutricional"),("Para la ricota","¼ cucharadita de ajo en polvo"),("Para la ricota","¾ cucharadita de sal marina"),("Para la ricota","½ taza de agua"),("Para la ricota","1 paquete de 5 onzas de espinacas baby (aprox. 3-4 puñados grandes o 1 taza ya salteadas)"),
("Para la salsa boloñesa","1 taza de salsa de tomate o su salsa marinara favorita"),("Para la salsa boloñesa","½ taza de nueces de Castilla picadas"),("Para la salsa boloñesa","¼ cucharadita de sal marina"),("Para la salsa boloñesa","¼ cucharadita de albahaca seca"),("Para la salsa boloñesa","¼ cucharadita de orégano seco"),("Para la salsa boloñesa","¼ cucharadita de ajo en polvo"),
("Guarnición opcional","queso parmesano vegano"),("Guarnición opcional","perejil fresco")],
["Precaliente el horno a 400℉/204℃ y cubra una bandeja grande para hornear con papel pergamino.",
"Limpie los hongos con un cepillo y raspe las láminas con una cucharadita de metal. Tenga cuidado de no romper los hongos. Luego colóquelos con el tallo hacia abajo en la bandeja. Espolvoree la parte superior con sal y pimienta y hornee durante 10 minutos. Este paso permite que los hongos suelten parte de la humedad para que no queden aguados después.",
"Mientras tanto, saltee las espinacas en una sartén a fuego medio hasta que se marchiten. Agregue una o dos gotas de agua si es necesario para empezar. Revuelva con frecuencia para evitar que se peguen. Una vez marchitas, exprima la mayor cantidad posible de líquido de las espinacas con un paño de cocina limpio, una bolsa para leche vegetal o una toalla de papel. Reserve.",
"Ponga en un procesador de alimentos los ingredientes de la ricota, EXCEPTO las espinacas. Procese hasta obtener una mezcla suave, raspando los lados según sea necesario. Cuando esté suave, agregue las espinacas y pulse 3-4 veces para incorporarlas. NO procese en exceso o el queso se volverá verde.",
"Luego, combine todos los ingredientes de la salsa boloñesa en un tazón pequeño. Revuelva y reserve.",
"Saque los hongos del horno y voltéelos con el tallo hacia arriba. Absorba el exceso de humedad presionando los hongos con un paño de cocina limpio o una toalla de papel.",
"Divida la ricota entre los seis hongos. Luego cubra cada uno con la salsa boloñesa. Hornee los hongos rellenos durante 10-12 minutos, retírelos del horno y sirva con perejil fresco, hojuelas de pimiento rojo y/o queso parmesano vegano."],
["Si no tiene un procesador de alimentos potente, remoje los anacardos en agua hirviendo durante 15-30 minutos y escúrralos antes de preparar la ricota.",
"Si usa espinacas congeladas, mida aproximadamente 1 taza, descongélelas y exprima la mayor cantidad posible de humedad con una bolsa para leche vegetal, un paño de cocina o toallas de papel.",
"No procese en exceso las espinacas al preparar la ricota. Solo pulse unas cuantas veces para mezclarlas. Debe ver hebras de espinaca en la ricota, y no un queso verde.",
"Para convertirlos en aperitivos, use aproximadamente 2-3 veces más sombreros de hongo o champiñones cremini, según su tamaño.",
"Si desea planificar con anticipación, prepare la ricota y la salsa boloñesa y refrigérelas por separado de 2 a 3 días antes. Luego rellene y hornee los hongos el día de servir.",
"Las sobras se conservan refrigeradas de 2 a 3 días en un recipiente sellado."],[]))
X.append(r(9279723,"Dip vegano de espinacas y alcachofas [sin aceite]","¡Un dip vegano de espinacas y alcachofas cremoso, derretido y totalmente delicioso! Este divertido aperitivo es tan elástico y cremoso que nadie creerá que es vegano.","8 porciones","1 porción",
["2 puñados grandes de espinacas frescas o 2 tazas de espinacas congeladas*","1 lata de 13.5 onzas de corazones de alcachofa en agua, no marinados (aprox. 1.5 tazas)","1 taza de anacardos (nueces de la India) crudos","2 tazas de agua","⅓ taza de levadura nutricional","½ taza de fécula de tapioca o harina de tapioca","3 dientes de ajo pelados","1 cucharada de vinagre blanco","1.5 cucharaditas de sal marina","¾ taza de leche de anacardo sin azúcar o la leche vegetal de su preferencia",("Guarnición opcional","queso parmesano vegano")],
["Escurra y enjuague las alcachofas, córtelas en rebanadas finas y resérvelas.",
"Ponga todos los ingredientes, EXCEPTO las alcachofas y las espinacas, en una licuadora de alta velocidad. Procese hasta que esté suave; quedará muy líquido, pero espesará al cocinarse.",
"Vierta la mezcla en una sartén antiadherente o use una sartén apta para horno, como una de hierro fundido, si desea gratinar el dip después. Agregue a la sartén las alcachofas en rebanadas y las espinacas. Cocine a fuego medio, revolviendo con frecuencia, durante unos 5 minutos, hasta que esté espeso y burbujeante.",
"OPCIONAL: Ponga el horno en la función de asar (broil) a temperatura alta. Luego pase el dip a un recipiente apto para horno (si no está en uno). Ase durante 2-5 minutos hasta que esté dorado y burbujeante por encima. Vigile con atención para evitar que se queme. Retire del horno.",
"Espolvoree con queso parmesano vegano, si lo usa. Luego sirva caliente con totopos, galletas saladas, verduras crudas, pan o cualquiera de sus acompañamientos favoritos."],
["* Si usa espinacas congeladas, asegúrese de exprimirlas y escurrirlas lo más posible antes de agregarlas a la sartén. Si no tiene una licuadora de alta velocidad, remoje primero los anacardos en agua hirviendo durante 15-30 minutos, luego escúrralos y úselos según las instrucciones. Esto ayudará a ablandarlos y a licuarlos con más facilidad. Si el dip queda demasiado espeso, agregue más leche o agua a la sartén para aligerarlo. Tenga en cuenta que se endurecerá al enfriarse y que, al recalentarlo, recuperará su textura sedosa. Para dar más profundidad de sabor, use caldo de verduras en lugar de agua. Para hacerlo picante, agregue ½ cucharadita de pimienta de cayena o 1-2 cucharaditas de su salsa picante favorita. Para un dip ahumado, agregue 1 cucharadita de pimentón ahumado. Para prepararlo con anticipación, licúe y cocine en la estufa según las indicaciones y refrigere hasta que lo necesite. Luego métalo al horno a 350°F/176°C para calentarlo durante unos 10-15 minutos. Después, áselo (broil) 2-5 minutos más para dorar la parte superior, si lo desea. Guarde las sobras refrigeradas en un recipiente sellado de 3 a 4 días, o congélelas en un recipiente hermético apto para congelador hasta por 3 meses. Receta inspirada en mi mozzarella vegana."],[]))
X.append(r(9279842,"Papas fritas veganas cargadas","¡Prepárese para disfrutar las mejores papas fritas veganas cargadas!","6 porciones","1 porción",
[("Para las papas","3 libras de papas russet"),("Para las papas","2 cucharadas de caldo de verduras o aceite de aguacate"),("Para las papas","½ cucharadita de sal marina o al gusto"),
("Para los acompañamientos","1 receta de salsa de queso sin frutos secos o el queso vegano de su elección"),("Para los acompañamientos","½ taza de frijoles rojos"),("Para los acompañamientos","½ taza de aceitunas negras"),("Para los acompañamientos","½ taza de maíz"),("Para los acompañamientos","1 tomate picado en cubos"),("Para los acompañamientos","1-2 cebollitas verdes en rodajas"),("Para los acompañamientos","1-2 jalapeños en rodajas, opcional"),
("Para mojar (opcional)","crema de anacardo"),("Para mojar (opcional)","guacamole"),("Para mojar (opcional)","salsa")],
["Precaliente el horno a 425℉/218℃ en la función de asado con convección y cubra una bandeja grande para hornear con papel pergamino.",
"Pele o frote las papas y córtelas en bastones con un cortador de papas fritas o un cuchillo afilado. Mézclelas con el caldo o el aceite y la sal. Luego colóquelas en una sola capa en la bandeja. Ase durante 20 minutos, luego voltéelas y continúe asando de 10 a 15 minutos más, o hasta lograr la textura crujiente deseada.",
"Mientras tanto, prepare la salsa de queso y los demás acompañamientos mientras se cocinan las papas.",
"Armado: Use una fuente grande o la misma bandeja que usó para hornear. Comience con las papas, siga con aproximadamente la mitad de la salsa de queso y luego espolvoree todos los demás acompañamientos en el orden que prefiera. Por último, termine rociando el resto de la salsa de queso por encima y sirva."],
["Acomode las papas en una sola capa con un poco de espacio entre ellas para que queden bien crujientes y no se peguen. Si su horno no tiene convección, espere un tiempo de cocción un poco más largo. Siga horneando hasta lograr la textura crujiente deseada."],[]))
X.append(r(9289404,"Galletas saludables de Halloween [¡nadie lo notará!]","¡Las galletas saludables de Halloween son el postre perfecto para complacer tanto a los niños como a los adultos!","26 galletas","1 porción",
["1.5 tazas de garbanzos cocidos o enlatados","2 plátanos (bananas) medianos maduros (con un peso de 230 gramos con cáscara)","¼ taza de miel de maple","½ taza de mantequilla de cacahuate (maní), casera o comprada (o sustituya por mantequilla de soya si es sin frutos secos)","2 cucharadas de puré de manzana sin azúcar","1 taza de avena en hojuelas, sin gluten si lo prefiere","3 puñados grandes de espinacas baby","1 cucharadita de polvo para hornear",("Opcional","chispas de chocolate O ojitos de dulce")],
["Precaliente el horno a 350℉/176℃ y cubra dos bandejas para hornear con papel pergamino.",
"Ponga todo en el procesador de alimentos, EXCEPTO los ingredientes opcionales, y procese hasta que quede suave.",
"Use un cucharón pequeño para galletas para colocar la masa en las bandejas. Obtendrá unas 26 galletas. Luego, con las manos ligeramente húmedas o con el dorso de una cuchara, presione las galletas y deles forma de círculos. La masa no se extiende mucho, así que deles forma antes de hornear.",
"OPCIONAL: Si usa chispas de chocolate para los ojos, agréguelas ahora a las galletas. Si usa ojitos de dulce, agréguelos DESPUÉS de hornear.",
"Hornee de 16 a 18 minutos, luego saque las galletas del horno y presione suavemente los ojitos de dulce (si los usa) en las galletas mientras aún están tibias. Para hacer las bocas, use un palillo de dientes o el extremo de una cuchara o tenedor para dibujar diferentes formas de boca en cada una de sus galletas espeluznantes. Luego déjelas enfriar."],
["Use plátanos MUY maduros, con manchas marrones, ya que no tiene mucho endulzante adicional.","Si usa los ojitos de dulce, presiónelos en las galletas inmediatamente después de sacarlas del horno, mientras aún están tibias.","Haga divertidas formas de boca en sus galletas verdes mientras aún están tibias. Use un palillo de dientes o la punta o el extremo de una cuchara o tenedor."],[]))
X.append(r(9291733,"Ensalada de col vegana sin aceite","Una ensalada de col vegana cremosa y deliciosa, crujiente, ácida y llena de sabor.","8 porciones","1 porción",
["2 libras de col morada (aprox. 6-7 tazas rallada)","2 zanahorias grandes (aprox. 1-2 tazas ralladas)","1 taza de mayonesa vegana sin aceite casera o comprada","1.5 cucharadas de miel de maple o jarabe de dátil","1.5 cucharadas de vinagre blanco","1 cucharada de mostaza amarilla","¼ cucharadita de pimienta negra"],
["Ralle la col y las zanahorias y póngalas en un tazón grande.","En un tazón pequeño, combine la mayonesa, la miel de maple, el vinagre, la mostaza y la pimienta negra. Bata hasta integrar. Luego vierta el aderezo sobre la ensalada de col y mezcle hasta que quede cubierta de manera uniforme."],
["Para que sea sin aceite, use mi mayonesa de pepitas para esta receta. La mayonesa comprada suele tener MUCHO aceite.","Para una opción sin mayonesa, pruebe nuestra ensalada de col con aderezo de cacahuate.","Use ensalada de col rallada comprada para una preparación más rápida. Use 6-8 tazas de su mezcla favorita.","Pruebe el aderezo antes de verterlo sobre la ensalada y ajuste el sazón si es necesario. Conviene que el aderezo tenga un sabor muy marcado, ya que las verduras no están sazonadas.","Para la ensalada, me gusta la col morada por su color vibrante, pero puede usar col verde o una mezcla de ambos colores, si lo prefiere. Otras adiciones incluyen perejil, cilantro, apio, cebollita verde o cebolla morada.","Para el aderezo, puede agregar más sazón si lo desea. Algunas opciones incluyen semillas de apio, comino, chile en polvo, ajo en polvo, pimentón ahumado o pimienta de cayena.","Esta ensalada de col vegana sabe mejor el mismo día en que se prepara; sin embargo, las sobras se conservan en el refrigerador hasta por 3 días.","La información nutricional incluye mi mayonesa de pepitas. Si la sustituye por una comprada, tendrá más calorías y grasa."],[]))
X.append(r(9293583,"Papas fritas de zanahoria en freidora de aire [sin aceite]","¡Una alternativa más saludable a las papas fritas que satisfará su antojo con una fracción de las calorías y la grasa! No necesita aceite para estas crujientes papas fritas de zanahoria en freidora de aire, llenas de excelente sabor.","2 porciones","1 porción",
["1 libra de zanahorias (aprox. 3 zanahorias medianas/grandes)","1 cucharada de fécula de tapioca, también conocida como harina de tapioca","½ cucharadita de sal marina","½ cucharadita de ajo en polvo","½ cucharadita de cebolla en polvo","½ cucharadita de tomillo seco, opcional","1-2 cucharadas de parmesano vegano, opcional",("Dip para servir (opcional)","mostaza con miel vegana"),("Dip para servir (opcional)","mayonesa con sriracha")],
["Pele y corte las zanahorias en bastones de 4 pulgadas, de aprox. 1/4 de pulgada de grosor, para que se cocinen de manera uniforme.",
("Instrucciones para freidora de aire","Ponga las zanahorias y todos los demás ingredientes en un tazón mediano y mezcle hasta que queden cubiertas de manera uniforme; luego acomódelas en la canasta en una capa uniforme. (Pueden quedar encimadas.)"),
("Instrucciones para freidora de aire","Cocine en la freidora de aire a 400 grados F (204 grados C) durante 15-20 minutos, hasta lograr la textura crujiente deseada, moviéndolas una vez a la mitad del tiempo."),
("Instrucciones para horno","Precaliente el horno a 450 grados F (232 grados C) y cubra una bandeja grande para hornear con papel pergamino."),
("Instrucciones para horno","Agregue al tazón la fécula de tapioca, la sal, el ajo en polvo, la cebolla en polvo y el tomillo, y mezcle hasta que todas las zanahorias queden cubiertas de manera uniforme. Luego extienda las zanahorias en una sola capa sobre la bandeja preparada, dejando espacio entre cada una para que ninguna quede encimada."),
("Instrucciones para horno","Hornee durante 20 minutos, luego saque la bandeja del horno, voltee las papas de zanahoria y espolvoree con el queso parmesano vegano. Regrese al horno por 10 minutos más, o hasta lograr la textura crujiente deseada.")],
["Haga lo posible por cortar las papas de zanahoria lo más uniformes posible para que se cocinen de manera pareja. Elija zanahorias que tengan el mismo ancho de arriba a abajo, si es posible. El tiempo de cocción variará según el método que use (horno o freidora de aire), así como según el tamaño de las papas de zanahoria. Puede preparar las zanahorias hasta con 1 día de anticipación y mantenerlas refrigeradas en el tazón con el sazón, hasta el momento de hornear. Si no encuentra fécula o harina de tapioca, puede sustituirla por maicena con resultados similares. Estas zanahorias saben mejor recién horneadas, pero puede refrigerar las sobras hasta por 3 días."],[]))
X.append(r(9295060,"Ensalada de papa y espárragos","Esta vibrante ensalada de papa y espárragos es una perfecta celebración de los sabores de la primavera.","6 porciones","1 porción",
[("Para la ensalada de papa","2 libras de papas pequeñas bien lavadas (usé una mezcla de rojas y amarillas)"),("Para la ensalada de papa","1 libra de espárragos, sin los extremos duros y cortados en trozos de 1 pulgada"),("Para la ensalada de papa","1 taza de chícharos (guisantes) congelados"),("Para la ensalada de papa","2-3 cucharadas de cebolla morada picada en cubos"),
("Para el aderezo","¼ taza de jugo de limón"),("Para el aderezo","1 cucharada de tahini o mantequilla de almendra"),("Para el aderezo","1 cucharada de miel de maple"),("Para el aderezo","1 cucharadita de mostaza amarilla"),("Para el aderezo","1 cucharadita de ajo en polvo"),("Para el aderezo","1 cucharadita de orégano seco"),("Para el aderezo","¼ taza de cebollín fresco picado finamente"),("Para el aderezo","sal + pimienta al gusto")],
["Hierva una olla grande con agua con sal.",
"Agregue los chícharos y los espárragos y cocine de 2 a 3 minutos. Luego retírelos con una espumadera y páselos a un tazón grande.",
"Después, agregue las papas pequeñas y cocínelas hasta que se puedan atravesar fácilmente con un tenedor, aprox. 15-20 minutos. Escúrralas y enjuáguelas hasta que se enfríen lo suficiente para manipularlas.",
"Mientras se cocinan las papas, ponga los ingredientes del aderezo en un tazón pequeño o frasco y mezcle bien. Si es necesario, agregue unas gotas de agua para aligerar el aderezo.",
"Corte las papas cocidas por la mitad (o en cuartos si son más grandes) y agréguelas, junto con la cebolla morada, al tazón de chícharos y espárragos. Luego agregue el aderezo y revuelva hasta que todo quede cubierto de manera uniforme."],
["Pruebe el aderezo para ver si necesita sal y pimienta antes de mezclarlo con la ensalada. Ajuste si es necesario.","Puede preparar esta ensalada de papa y espárragos con anticipación y mantenerla refrigerada de 1 a 2 días antes de servir."],[]))
X.append(r(9296884,"Sopa de coliflor asada","Esta sopa de coliflor asada es rica, aterciopelada y sorprendentemente fácil de preparar.","4 porciones","1 porción",
["6 tazas de floretes de coliflor (aprox. 1 coliflor mediana)","1 cebolla amarilla (en cuartos)","3 dientes de ajo (con la cáscara)","4 tazas de caldo de verduras bajo en sodio","1 cucharada de pasta de miso blanco","1/3 taza de levadura nutricional","1-2 cucharadas de jugo de limón (comience con 1)","15 onzas de frijoles cannellini blancos (escurridos + enjuagados)","sal y pimienta (al gusto)"],
["Precaliente el horno a 425℉ en la función de asado con convección y cubra una bandeja grande para hornear con papel pergamino.",
"Corte la coliflor en floretes pequeños para que se cocine rápido. Corte la cebolla en cuartos y deje la cáscara a los ajos. Acomódelos en una sola capa en la bandeja y ase durante 20 minutos, o hasta que estén dorados.",
"Una vez asadas, pase las verduras y todos los demás ingredientes a la licuadora, trabajando por tandas si es necesario. Licúe la sopa hasta que quede suave, pero reserve unos trozos de coliflor para decorar los tazones, si lo desea."],[],[]))
X.append(r(9297046,"Papas en cubos en freidora de aire","Un acompañamiento perfecto para cualquier comida, estas papas en cubos en freidora de aire son irresistibles.","2 porciones","1 porción",
["1 libra de papas russet cortadas en cubos de media pulgada (aprox. 3 papas medianas)","2 cucharadas de jugo de limón (aprox. medio limón grande)","1 cucharadita de ajo en polvo","½ cucharadita de tomillo seco","¼ cucharadita de sal marina o al gusto","¼ cucharadita de pimienta negra o al gusto"],
["Pele las papas y córtelas en cubos de aprox. media pulgada, procurando que tengan un tamaño lo más parecido posible para que se cocinen de manera uniforme.",
"Colóquelas en un tazón y cúbralas con agua fría; déjelas remojar durante 20 minutos. Luego escurra las papas y séquelas con palmaditas. Enjuague y seque el tazón que usó para remojar y regrese las papas al tazón.",
"Agregue el jugo de limón y los condimentos, y mezcle bien para cubrir los trozos de manera uniforme.",
"Con una cuchara (sin verterlas de golpe), coloque las papas sazonadas en la canasta de la freidora en una sola capa y cocine en la freidora de aire a 400℉/204℃ durante 15-20 minutos. Mezcle o sacuda la canasta cada 5 minutos hasta lograr la textura crujiente deseada. ¡Disfrútelas!"],
["Corte las papas lo más parejas posible para que se cocinen y queden crujientes de manera uniforme.","No omita el paso de remojar, ya que ayuda a eliminar parte del almidón de las papas y da resultados más crujientes, sin necesidad de aceite.","Para papas aún más crujientes, puede agregar 1 cucharadita de un aceite de buena calidad, como aceite de aguacate, a la mezcla. (No recomiendo cocinar con aceite de oliva debido a su bajo punto de humeo.)"],[]))
X.append(r(9305421,"Galletas veganas con chispas de chocolate [sin aceite]","Solo 8 ingredientes y 20 minutos para una deliciosa y saludable galleta de origen vegetal. ¡Son esponjosas, suaves y adictivas!","20 galletas","1 porción",
[("Ingredientes secos","180 gramos de harina de avena, sin gluten si lo prefiere (aprox. 1.5 tazas)"),("Ingredientes secos","1.5 cucharaditas de polvo para hornear"),("Ingredientes secos","¼ cucharadita de sal marina"),
("Ingredientes húmedos","⅓ taza de leche de soya"),("Ingredientes húmedos","⅓ taza de miel de maple"),("Ingredientes húmedos","¼ taza de puré de manzana sin azúcar"),("Ingredientes húmedos","1 cucharadita de extracto puro de vainilla"),
("Complemento opcional (pero recomendado)","⅓ taza de chispas de chocolate oscuro")],
["Precaliente el horno a 350℉/176℃ y cubra una bandeja grande para hornear con papel pergamino.",
"Bata juntos los 3 ingredientes secos en un tazón pequeño y reserve. En otro tazón mediano, combine los ingredientes húmedos y mezcle bien. Luego agregue los ingredientes secos y las chispas de chocolate al tazón de los ingredientes húmedos y revuelva para integrar.",
"Use un cucharón para galletas o una cucharada para colocar la mezcla en la bandeja preparada y hacer aprox. 20 galletas, dejando espacio entre cada una.",
"Hornee durante 10 minutos, luego saque las galletas del horno y déjelas enfriar durante 10 minutos antes de pasarlas a una rejilla de enfriamiento. Disfrútelas tibias, o deje que se enfríen hasta alcanzar la temperatura ambiente y disfrútelas."],
["Pese la harina para obtener los resultados más precisos. Sacar la harina de la bolsa con la taza suele hacer que se use demasiada harina y que el resultado quede seco. Si no tiene una báscula de cocina, ponga la harina con una cuchara en las tazas medidoras y nivélela con el dorso de un cuchillo.","Use polvo para hornear ACTIVO. Una vez abierto, después de más de 6 meses en la despensa, el polvo para hornear comienza a perder su efectividad.","La masa se verá similar a una masa de panqueques, y es lo esperado. Recuerde que estas son galletas de origen vegetal bajas en grasa y no las comunes llenas de mantequilla.","Deje que las galletas se enfríen durante 10 minutos después de sacarlas del horno, antes de manipularlas. Este tiempo de enfriamiento les ayudará a firmarse y a asentarse.","Es mejor servirlas en 1-2 días, pero se conservan de 2 a 3 días a temperatura ambiente, hasta 5 días refrigeradas, o congeladas hasta por 3 meses."],[]))
X.append(r(9306532,"Ejotes en freidora de aire","Ejotes (judías verdes) tiernos y crujientes con limón en freidora de aire. Son sabrosos, muy sencillos de preparar y están listos en 15 minutos o menos.","4 porciones","1 porción",
["14 onzas (400 gramos) de ejotes (judías verdes), sin los extremos","2 cucharadas de jugo de limón","¼ cucharadita de ajo en polvo","¼ cucharadita de sal marina o al gusto","¼ cucharadita de pimienta negra o al gusto",("Guarnición opcional","1-2 cucharadas de queso parmesano vegano")],
["Corte los extremos de los ejotes y póngalos en un tazón mediano. Agregue el jugo de limón y los condimentos y mezcle para cubrir los ejotes de manera uniforme.",
"Colóquelos en la canasta y cocine en la freidora de aire a 380 grados F (193 grados C) durante 8-12 minutos, hasta que estén dorados. Mezcle a la mitad de la cocción.",
"Retire los ejotes de la freidora y espolvoree con el queso parmesano opcional, si lo desea. Disfrute."],
["Consejo rápido para cortar los extremos de los ejotes. Alinee varios a la vez y corte los extremos; luego gírelos y corte el otro lado. Es mucho más rápido que cortar un ejote a la vez."],[]))
X.append(r(9307320,"Rizos de soya crujientes estilo búfalo","¡Rizos de soya estilo búfalo crujientes, picantes y adictivos! Perfectos para el día del partido, una cita romántica o cualquier noche.","6 porciones","1 porción",
["8 onzas de rizos de soya (soy curls)","2 tazas de caldo de verduras bajo en sodio","2 cucharaditas de ajo en polvo","2 cucharaditas de cebolla en polvo","2 cucharaditas de pimentón ahumado","2 cucharaditas de condimento para aves",
("Salsa búfalo","½ taza de salsa picante Frank's RedHot Original"),("Salsa búfalo","2 cucharadas de mantequilla de almendra, mantequilla de anacardo o tahini"),("Para servir","aderezo ranch vegano"),("Para servir","bastones de zanahoria y apio")],
["Precaliente el horno a 400°F/204°C en la función de horneado con convección y cubra una bandeja grande para hornear (o 2 medianas) con papel pergamino.",
"Combine el caldo de verduras, el ajo en polvo, la cebolla en polvo, el pimentón ahumado y el condimento para aves en una taza medidora grande o un tazón. Bata bien para integrar.",
"Luego coloque los rizos de soya en un tazón grande, vierta la mezcla de caldo encima y mezcle bien. Déjelos reposar 10 minutos, revolviendo cada pocos minutos, hasta que se absorba el líquido.",
"Mientras espera a que los rizos se hidraten, ponga la salsa picante y la mantequilla de almendra en un tazón pequeño y mezcle bien hasta que quede suave. Luego vierta la salsa búfalo que acaba de preparar sobre los rizos hidratados y mezcle hasta que queden cubiertos de manera uniforme.",
"Acomódelos en una sola capa en la bandeja, sin que se encimen. Hornee durante 20 minutos, luego voltéelos y hornee de 12 a 15 minutos más hasta lograr la textura crujiente deseada.",
"Sirva con aderezo ranch, zanahorias y bastones de apio."],
["No vierta los rizos búfalo del tazón a la bandeja de golpe. No conviene que el exceso de líquido se acumule en la bandeja y los haga menos crujientes.","Acomódelos en una sola capa con un poco de espacio entre cada uno para que queden bien crujientes al hornearse.","Al voltear los trozos de soya, asegúrese nuevamente de acomodarlos en una sola capa con espacio entre cada uno para lograr la máxima textura crujiente."],[]))
X.append(r(9310264,"Cupcakes veganos saludables de calabaza","Estos cupcakes veganos de calabaza, saludables sin que se note, se preparan con ingredientes sorprendentes para ofrecer un postre delicioso y a la vez nutritivo.","12 cupcakes","1 porción",
[("Ingredientes húmedos","1 taza de puré de calabaza (no relleno para pay de calabaza)"),("Ingredientes húmedos","¾ taza de leche de anacardo o de almendra sin azúcar"),("Ingredientes húmedos","½ taza de miel de maple"),
("Ingredientes secos","175 gramos de harina de almendra blanqueada superfina (aprox. 1 ¾ tazas)"),("Ingredientes secos","150 gramos de harina de avena fina (aprox. 1 ¾ tazas)"),("Ingredientes secos","2.5 cucharaditas de canela"),("Ingredientes secos","¼ cucharadita de jengibre molido"),("Ingredientes secos","¼ cucharadita de nuez moscada molida"),("Ingredientes secos","⅛ cucharadita de clavo molido"),("Ingredientes secos","2.5 cucharaditas de polvo para hornear"),("Ingredientes secos","¼ cucharadita de sal marina"),
("Ingredientes para el glaseado vegano de queso crema","340 gramos (12 onzas) de tofu extra firme en bloque, sin OGM si es posible"),("Ingredientes para el glaseado vegano de queso crema","¼ taza de anacardos (nueces de la India) crudos"),("Ingredientes para el glaseado vegano de queso crema","5-6 cucharadas de miel de maple"),("Ingredientes para el glaseado vegano de queso crema","2 cucharaditas de extracto puro de vainilla")],
["Precaliente el horno a 350°F/176°C y forre un molde para muffins con capacillos para cupcakes. Reserve.",
"Combine los ingredientes húmedos en un tazón grande y bata para integrar. Luego agregue todos los ingredientes secos y mezcle hasta que no queden grumos de harina, sin mezclar en exceso. (No se preocupe por algunos grumos.)",
"Divida la masa de los cupcakes entre los 12 moldes y hornee de 22 a 24 minutos, o hasta que un palillo insertado en el centro salga limpio. Retire del horno y deje enfriar por completo antes de glasear.",
"Para preparar el glaseado, ponga todos los ingredientes en la licuadora y procese hasta que quede completamente suave, comenzando con 5 cucharadas de miel de maple. Pruebe y agregue otra cucharada de miel si lo prefiere más dulce. Tenga en cuenta que no debe excederse, o el glaseado quedará demasiado líquido para decorar con manga pastelera.",
"Si el glaseado se calienta al licuarlo (esto puede ocurrir en licuadoras potentes), páselo a un tazón y colóquelo en el congelador durante 30 minutos antes de decorar los cupcakes con la manga pastelera."],
["Pese la harina para obtener los resultados más precisos. Le recomiendo encarecidamente que no dependa de las medidas en tazas al hornear. Si no tiene una báscula de cocina, puede poner la harina con una cuchara en la taza medidora y rasar el exceso con un cuchillo, con resultados similares. ¡No la saque directamente de la bolsa! Recomiendo usar harina de almendra superfina y harina de avena fina para obtener la mejor textura. También probé estos cupcakes con harina de avena casera y, aunque funciona bien, una harina de avena más fina dará una miga más ligera y delicada. Use polvo para hornear fresco y activo. El polvo para hornear que lleva abierto en la despensa más de 6 meses puede comenzar a perder su efectividad. Si no tiene una licuadora potente, remoje los anacardos en agua caliente durante 30 minutos antes de licuar el glaseado. Esto ayudará a que se hinchen y ablanden, para que sea más fácil licuarlos hasta obtener un glaseado suave. Asegúrese de prensar muy bien el tofu para eliminar el exceso de líquido y evitar que el glaseado quede demasiado líquido. Si el glaseado se calienta al licuarlo (esto puede ocurrir en licuadoras potentes), páselo a un tazón y colóquelo en el congelador durante 30 minutos antes de decorar los cupcakes con la manga pastelera. Deje que los cupcakes se enfríen en el molde para muffins durante al menos 20 minutos antes de manipularlos. Luego páselos a una rejilla de enfriamiento para que se enfríen por completo ANTES de glasearlos. Saben mejor los días 1-2, pero puede guardar las sobras en el refrigerador hasta por 4 días. Guárdelos en un recipiente sellado para conservar la humedad. O congélelos en un recipiente hermético apto para congelador hasta por 3 meses."],[]))
X.append(r(9315360,"Pan de plátano con trigo sarraceno","Este pan de plátano (banana) con trigo sarraceno es delicioso, nutritivo y perfecto para un desayuno, una merienda o un postre saludable.","12 rebanadas","1 porción",
[("Ingredientes húmedos","1 taza de plátano (banana) machacado (aprox. 3 medianos o 2 grandes)"),("Ingredientes húmedos","⅓ taza de puré de manzana sin azúcar"),("Ingredientes húmedos","⅓ taza de leche de soya, de almendra o de anacardo"),
("Ingredientes secos","200 gramos de harina de trigo sarraceno (aprox. 1.5 tazas)"),("Ingredientes secos","¼ taza de azúcar de coco"),("Ingredientes secos","2 cucharaditas de polvo para hornear"),("Ingredientes secos","1 cucharadita de canela"),
("Coberturas opcionales","¼ taza de nueces de Castilla o nueces pecanas picadas"),("Coberturas opcionales","plátano (banana) en rodajas"),("Coberturas opcionales","azúcar de coco para espolvorear")],
["Precaliente el horno a 350°F/176°C y forre un molde para pan con papel pergamino.",
"Machaque el plátano y ponga 1 taza completa en un tazón mediano, luego agregue la leche y el puré de manzana. Mezcle bien. Después agregue todos los ingredientes secos al mismo tazón y mezcle hasta integrar.",
"Vierta la masa en el molde forrado y cubra con rodajas de plátano, nueces y un poco de azúcar de coco espolvoreada. Asegúrese de presionar suavemente las coberturas sobre la superficie del pan.",
"Hornee hasta que un palillo insertado en el centro salga casi limpio y seco, aprox. 40-50 minutos, según su horno."],
["Pese la harina con una báscula de cocina para obtener los resultados más precisos. Sacar la harina de la bolsa con la taza suele hacer que se use demasiada harina y puede dejar este pan seco y denso.","Use plátanos muy maduros. Mientras más manchas marrones tengan, mejor, ya que serán más dulces. Como la receta usa muy poco endulzante, debe asegurarse de que los plátanos aporten suficiente dulzor.","Mida los plátanos machacados. El tamaño de los plátanos varía mucho. Por eso, asegúrese de usar la cantidad suficiente para lograr el dulzor y la humedad óptimos. Mida para confirmar que está usando una taza completa de plátano machacado.","¡Use polvo para hornear fresco + activo! El polvo para hornear que lleva abierto en la despensa más de 6 meses puede comenzar a perder su efectividad.","Use papel pergamino para forrar el molde para pan. Aunque un molde antiadherente debería funcionar, me resulta mucho más fácil desmoldarlo con papel pergamino. Puede levantar el pan fácilmente y colocarlo en una rejilla sin temor a que se rompa.","Cada horno es diferente. Por eso, asegúrese de comprobar si su pan de plátano con trigo sarraceno está listo insertando un palillo en el centro. Cuando salga casi seco, el pan está listo.","Déjelo enfriar. Dese tiempo extra para que el pan se enfríe. Se recomienda un mínimo de 20-30 minutos en una rejilla de enfriamiento para que se asiente por completo y sea mucho más fácil de rebanar.","Las sobras se conservan a temperatura ambiente de 2 a 3 días, refrigeradas de 4 a 5 días, o congeladas en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9316983,"Sándwiches veganos de pepino con eneldo","¡El queso crema espeso y cremoso con pepino y eneldo fresco hace de estos los mejores sándwiches veganos de pepino que probará!","6 porciones","1 porción",
["1 taza de queso crema vegano","2 cucharadas de eneldo fresco, sin los tallos gruesos y picado","1 cucharada de cebollita verde en rodajas finas","¼ cucharadita de ajo en polvo","¼ cucharadita de cebolla en polvo","sal + pimienta al gusto","½ pepino largo en rodajas finas (aprox. 18 rodajas)","6 rebanadas de pan integral de caja"],
["Ponga el queso crema con el eneldo, la cebollita verde y todos los condimentos en un tazón pequeño. Mezcle para integrar. Pruebe para ver si necesita sal y pimienta y agregue más, si es necesario.",
"Opcional: Use un cuchillo afilado para quitar las orillas del pan para obtener los clásicos sándwiches de pepino. O déjelas para dar más textura y fibra.",
"Unte generosamente el queso crema con hierbas en 3 rebanadas de pan, luego acomode encima las rodajas de pepino y espolvoree un poco de sal y pimienta sobre las rodajas de pepino, si lo desea. Coloque las otras 3 rebanadas de pan sobre los pepinos.",
"Corte cada sándwich en mitades o cuartos y sirva."],
["Use pepinos ingleses, no de campo. Los primeros tienen menos semillas y la cáscara más delgada, por lo que no es necesario pelarlos ni quitarles las semillas. Los segundos tienen la cáscara más gruesa y semillas amargas. Para que sea sin aceite: La receta es sin aceite tal como está escrita; sin embargo, muchos panes de caja comprados contienen aceite, así que asegúrese de leer los ingredientes. Como alternativa, puede preparar su propio pan integral sin aceite. Solo asegúrese de omitir el higo y las nueces de Castilla de esa receta de pan para estos sándwiches. Puede usar queso crema vegano comprado o el casero que preparo. Si usa la versión casera, necesitará aproximadamente la mitad de la receta de queso para preparar estos sándwiches. Los sándwiches sobrantes se conservan refrigerados de 2 a 3 días en un recipiente sellado o una bolsa con cierre. Sin embargo, saben mejor el mismo día en que se preparan."],[]))
save(1,X)
